import{_ as i,C as t,c as r,o as s,aj as l,G as a,w as d}from"./chunks/framework.Bfdr4H5E.js";const v=JSON.parse('{"title":"Taking Action – Alternate Strategies","description":"","frontmatter":{"outline":"deep","prev":{"text":"The Development Stages","link":"/trading-with-pav/the-development-stages"},"next":{"text":"Challenges and Difficulties","link":"/trading-with-pav/challenges-and-difficulties"}},"headers":[],"relativePath":"trading-with-pav/taking-action-alternate-strategies.md","filePath":"trading-with-pav/taking-action-alternate-strategies.md"}'),p={name:"trading-with-pav/taking-action-alternate-strategies.md"};function c(h,e,u,m,g,f){const o=t("GraphComment"),n=t("ClientOnly");return s(),r("div",null,[e[0]||(e[0]=l('<h1 id="taking-action-–-alternate-strategies" tabindex="-1">Taking Action – Alternate Strategies <a class="header-anchor" href="#taking-action-–-alternate-strategies" aria-label="Permalink to &quot;Taking Action – Alternate Strategies&quot;">​</a></h1><p>If having done this course and reading these article you find the strategy does not suit your psychology, or your view of the markets, or whatever else, that’s absolutely fine. You can develop your own approach, or refer to our Resources Page for recommended alternates: <a href="/sk/resources.html">https://www.ystc.in/resources</a> and our <a href="/sk/bookstore/">bookstore</a>.</p><p>This course series and articles will have provided you with a good foundation, and an understanding of the type of processes you’ll need to develop.</p><p>You will need to clearly document the fundamental principles behind how you see the markets and price movement, and where that offers trade opportunity. From there you will develop your trading plan and your procedures manual. This will take time, via another process of trial and error.</p><p>To discover the fundamental principles behind your strategy, you will benefit greatly from a period of time just watching price action.</p><p>Study live markets for as long as necessary, to gain a feel for how it moves. Study the different environments and the way price moves within each.</p><p>When comfortable with the movement of price, only then look for the trade opportunity within that movement. How can you identify the opportunity in advance? How can you gain a wholesale entry within that setup area?</p><p>In my opinion, it’s all about how price interacts with areas of previous supply/demand imbalance. You may not like my way of identifying and trading these areas, but by watching price and volume as it interacts with areas of S/R, swing highs and lows, and pullbacks within a trend, you’ll find your own patterns for future price movement and for possible trade opportunity.</p><p>Remember though, trading is NOT about fixed rules or simple setups.</p><p>I’ve provided rules and structure within this course with lifetime access to articles, as I’ve attempted to define what was largely a subjective and intuitive process as clearly as possible, for learning purposes. But within my rules there is much room for subjectivity. You’ll need to do the same. It’s how the market works!</p><div class="tip custom-block"><p class="custom-block-title">Remember</p><p><strong>It’s not about simple rules for providing certainty. It’s about getting better at making subjective decisions in uncertainty.</strong></p></div><p>Having defined your strategy, I then recommend implementing the same process defined in <a href="/sk/trading-with-pav/the-development-stages/">The Development Stages</a>, for advancing through the four stages of trader development.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',13)),a(n,null,{default:d(()=>[a(o)]),_:1})])}const w=i(p,[["render",c]]);export{v as __pageData,w as default};
